    pub fn roughen(mut self, seed: u32, period: f32, amount: f32, edge: f32) -> Self {
        let n = Fbm::new(seed, 5, period);
        let inv = 1.0 / self.f.scale;
        let w = self.f.w;
        self.data.par_chunks_mut(w).enumerate().for_each(|(y, row)| {
